INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(65433790, 'Battle Royal Mode - Joining', '大混战模式-加入', 'Battle Royal Mode－Joining', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '以场上1只效果怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，作为对象的怪兽1回合最多2次不会被战斗破坏。作为对象的怪兽被战斗破坏时让造成破坏的玩家回复2000基本分。 ②：从回合玩家来看的对方玩家因战斗·效果受到伤害的场合发动。那个对方玩家可以让以下效果适用。 ●从手卡·卡组把1只4星以下的怪兽特殊召唤，失去2000基本分。'),
(74752631, 'Battle Shogun of the Six Samurai', '六武众之军大将', '六武衆の軍大将', 'Link Monster', 'Warrior', 'EARTH', NULL, 1000, NULL, '包含「六武众」怪兽的战士族怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合，丢弃1张手卡才能发动。把持有把武士道指示物放置效果的1张卡从卡组加入手卡。 ②：只要这张卡在怪兽区域存在，每次这张卡所连接区有「六武众」怪兽召唤·特殊召唤，给这张卡放置1个武士道指示物。 ③：这张卡的攻击力上升自己场上的武士道指示物数量×100。'),
(18246479, 'Battle Steer', '牛魔人', '牛魔人', 'Normal Monster', 'Beast-Warrior', 'EARTH', 5, 1800, 1300, '住在森林里的牛魔人，用突起的角进行突袭。'),
(64178868, 'Battle Survivor', '战斗幸存者', 'バトル・サバイバー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 800, '这个卡名的效果1回合只能使用1次。 ①：自己·对方的战斗阶段结束时才能发动。从这次战斗阶段中在这只怪兽表侧表示存在期间被送去自己墓地的卡之中把「战斗幸存者」以外的1张卡从自己墓地选出加入手卡。'),
(71652522, 'Battle Teleportation', '战斗瞬间移动', 'バトル・テレポーテーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的念动力族怪兽只有1只的场合，选择那1只怪兽发动。这个回合选择怪兽可以直接攻击对方玩家。这个回合的战斗阶段结束时，选择怪兽的控制权转移给对方。'),
(5052212, 'Battle Tuned', '简易调和', 'イージーチューニング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从自己墓地把1只调整除外，以自己场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的攻击力上升因为这张卡发动而除外的调整的攻击力数值。'),
(15629801, 'Battle Waltz', '武斗圆舞', '武闘円舞', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只同调怪兽发动。把1只持有和那只怪兽相同种族·属性·等级·攻击力·守备力的「圆舞衍生物」在自己场上特殊召唤。这衍生物的战斗发生的对双方玩家的战斗伤害变成0。'),
(55550921, 'Battle Warrior', '格斗战士 阿提米特', '格闘戦士アルティメーター', 'Normal Monster', 'Warrior', 'EARTH', 3, 700, 1000, '不使用任何武器，空手战斗的格斗战士。'),
(94463200, 'Battle-Scarred', '血之刻印', '血の刻印', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己场上1只名称中含有「恶魔」字样的怪兽发动。所选择的怪兽在准备阶段支付基本分时，对方也要支付相同的基本分。当这张卡离场时，所选择的怪兽被破坏；当所选择的怪兽离场时，这张卡被破坏。'),
(40424929, 'Battlecruiser Dianthus', '烈华炮舰 抚子', '烈華砲艦ナデシコ', 'XYZ Monster', 'Plant', 'EARTH', 3, 2100, 1800, '3星怪兽×3 把这张卡1个超量素材取除才能发动。给与对方基本分对方手卡数量×200的数值的伤害。「烈华炮舰 抚子」的效果1回合只能使用1次。'),
(42228966, 'Battlefield Tragedy', '战场的惨剧', '戦場の惨劇', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：怪兽之间没有进行战斗的回合的自己主要阶段2，丢弃1张手卡才能发动。从卡组选1张「战场的惨剧」在自己的魔法与陷阱区域盖放。 ②：怪兽之间进行战斗的回合的结束阶段发动。回合玩家从自身卡组上面把5张卡送去墓地。'),
(5577149, 'Battleguard Cadet', '野蛮人0号', 'バーバリアン０号', 'Effect Monster', 'Warrior', 'EARTH', 1, 50, 100, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「蛮族的狂宴LV5」加入手卡。 ②：只要这张卡在怪兽区域存在，自己场上的「野蛮人」怪兽的攻击力上升500。 ③：把这张卡解放才能发动。从手卡把1只战士族·8星怪兽特殊召唤。'),
(74213995, 'Battleguard Echoes', '野蛮人回声阵', 'バーバリアン・エコーズ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只战士族·地属性·5星怪兽加入手卡。那个场合，再选自己1张手卡丢弃。 ②：1回合1次，场上的怪兽回到手卡的场合，可以从以下效果选择1个发动（伤害步骤也能发动）。 ●从卡组把1张「野蛮人之怒」或「野蛮人之吼」加入手卡。 ●场上1只表侧表示怪兽变成里侧守备表示。'),
(78621186, 'Battleguard Howling', '野蛮人之吼', 'バーバリアン・ハウリング', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的战士族怪兽成为对方怪兽的效果的对象时或者被选择作为对方怪兽的攻击对象时，以对方场上1只表侧表示怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害，那只怪兽回到持有者手卡。'),
(39389320, 'Battleguard King', '野蛮人国王', 'バーバリアン・キング', 'Effect Monster', 'Warrior', 'EARTH', 8, 3000, 1100, '①：1回合1次，把这张卡以外的自己场上的战士族怪兽任意数量解放才能发动。这个回合，这张卡在同1次的战斗阶段中在通常攻击外加上可以作出最多有为这个效果发动而解放的怪兽数量的攻击。'),
(42233477, 'Battleguard Rage', '野蛮人之怒', 'バーバリアン・レイジ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己场上1只战士族怪兽为对象才能把这张卡发动。那只怪兽的攻击力上升1000，那只怪兽战斗破坏的怪兽不送去墓地回到持有者手卡。作为对象的怪兽从场上离开时这张卡破坏。'),
(69695704, 'Battlestorm', '血风燕', 'ブラッドストーム', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1700, 1000, '这张卡的攻击力上升自己场上表侧表示存在的鸟兽族怪兽数量×100的数值。自己场上有鸟兽族怪兽表侧表示3只以上存在的场合，可以把对方场上存在的1张魔法·陷阱卡破坏。这个效果1回合只能使用1次。'),
(90161770, 'Battlewasp - Arbalest the Rapidfire', '蜂军－速击之劲弩', 'B・F－早撃ちのアルバレスト', 'Effect Monster', 'Insect', 'WIND', 4, 1800, 800, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1只3星以下的昆虫族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：这张卡被对方破坏的场合才能发动。从手卡·卡组把1只「蜂军」怪兽特殊召唤。'),
(27565379, 'Battlewasp - Azusa the Ghost Bow', '蜂军－灵弓之梓', 'B・F－霊弓のアズサ', 'Synchro Tuner Monster', 'Insect', 'WIND', 5, 2200, 1600, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡以外的「蜂军」怪兽的效果让对方受到伤害时才能发动（伤害步骤也能发动）。给与对方那只怪兽的原本攻击力数值的伤害。 ②：这张卡在墓地存在的状态，自己的「蜂军」怪兽的战斗让怪兽被破坏时才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(26443791, 'Battlewasp - Ballista the Armageddon', '蜂军－决战之重弩巨炮', 'B・F－決戦のビッグ・バリスタ', 'Synchro Monster', 'Insect', 'WIND', 12, 3000, 800, '调整＋调整以外的怪兽1只以上 ①：这张卡特殊召唤成功的场合，把自己墓地的昆虫族怪兽全部除外才能发动。对方场上的全部怪兽的攻击力·守备力下降除外中的自己的昆虫族怪兽数量×500。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：同调召唤的这张卡被对方破坏的场合才能发动。选除外的3只自己的11星以下的昆虫族怪兽特殊召唤。'),
(91283212, 'Battlewasp - Dart the Hunter', '蜂军－追击之飞镖', 'B・F－追撃のダート', 'Effect Monster', 'Insect', 'WIND', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「蜂军」怪兽战斗破坏原本持有者是对方的怪兽时，把这张卡从手卡丢弃才能发动。给与对方那只怪兽的原本攻击力数值的伤害。 ②：以这张卡以外的自己场上1只昆虫族怪兽为对象才能发动。这个回合，那只怪兽当作调整使用。这个效果的发动后，直到回合结束时自己不是昆虫族怪兽不能从额外卡组特殊召唤。'),
(35057188, 'Battlewasp - Grand Partisan the Revolution', '蜂军－革命之阔枪大游击', 'B・F－革命のグラン・パルチザン', 'Synchro Monster', 'Insect', 'WIND', 12, 3000, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，不会被效果破坏。 ②：自己场上的昆虫族同调怪兽的攻击力上升自己的除外状态的昆虫族怪兽数量×200。 ③：这张卡被除外的场合才能发动。这张卡特殊召唤。那之后，可以把最多有自己的除外状态的昆虫族怪兽数量的对方场上的卡破坏。那个场合，再给与对方破坏数量×500伤害。'),
(53950487, 'Battlewasp - Halberd the Charge', '蜂军－突击之钩镰枪', 'B・F－突撃のヴォウジェ', 'Synchro Monster', 'Insect', 'WIND', 6, 2500, 800, '昆虫族调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡向持有这张卡的攻击力以上的攻击力的对方怪兽攻击的伤害计算时才能发动1次。那只对方怪兽的攻击力只在伤害计算时变成一半。 ②：这张卡给与对方战斗伤害时才能发动。给与对方为自己场上的「蜂军」怪兽数量×200伤害。'),
(80949182, 'Battlewasp - Hama the Conquering Bow', '蜂军－降魔弓之破魔', 'B・F－降魔弓のハマ', 'Synchro Monster', 'Insect', 'WIND', 8, 2800, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：同调怪兽为素材作同调召唤的这张卡在同1次的战斗阶段中可以作2次攻击。 ②：这张卡给与对方战斗伤害时才能发动。对方场上的全部怪兽的攻击力·守备力下降1000。 ③：对方没有受到战斗伤害的自己战斗阶段的结束时才能发动。给与对方为自己墓地的「蜂军」怪兽数量×300伤害。'),
(25221249, 'Battlewasp - Nest', '蜂军之巢', 'B・F・N', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己的「蜂军」怪兽被选择作为攻击对象时才能发动。从手卡·卡组把1只「蜂军」怪兽特殊召唤，给这张卡放置1个指示物。那之后，战斗阶段结束。 ②：结束阶段，有指示物2个以上放置的这张卡送去墓地。'),
(65899613, 'Battlewasp - Pin the Bullseye', '蜂军－必中之图钉', 'B・F－必中のピン', 'Effect Monster', 'Insect', 'WIND', 1, 200, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有昆虫族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。给与对方为自己场上的「蜂军-必中之大头针蜂」数量×200伤害。'),
(56146300, 'Battlewasp - Rapier the Onslaught', '蜂军－猛击之针刺剑', 'B・F－猛撃のレイピア', 'Effect Monster', 'Insect', 'WIND', 5, 1900, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示怪兽不存在的场合或者只有昆虫族怪兽的场合，从手卡丢弃1只其他的昆虫族怪兽才能发动。从卡组把1张「蜂军风」在自己的魔法与陷阱区域表侧表示放置。那之后，这张卡从手卡特殊召唤。这个回合，自己不是昆虫族怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。自己场上1只昆虫族怪兽的等级下降1星。'),
(71456737, 'Battlewasp - Sachi the Ceremonial Bow', '蜂军－神事弓之福', 'B・F－神事弓のサチ', 'Synchro Monster', 'Insect', 'WIND', 6, 2400, 1200, '昆虫族调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。这张卡当作调整使用。 ②：1回合1次，让自己场上1张永续魔法卡回到手卡才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「蜂军」怪兽召唤。 ③：这张卡作为同调素材送去墓地的场合才能发动。给与对方为自己的除外状态的「蜂军」怪兽数量×100伤害。'),
(28388927, 'Battlewasp - Sting the Poison', '蜂军－毒针之尖刺', 'B・F－毒針のニードル', 'Tuner Monster', 'Insect', 'WIND', 2, 400, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「蜂军-毒针之针刺蜂」以外的1只「蜂军」怪兽加入手卡。 ②：把这张卡以外的自己场上1只昆虫族怪兽解放，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(54772065, 'Battlewasp - Twinbow the Attacker', '蜂军－连击之双弓', 'B・F－連撃のツインボウ', 'Effect Monster', 'Insect', 'WIND', 3, 1000, 500, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是昆虫族怪兽不能从额外卡组特殊召唤。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。'),
(67441879, 'Battlewasp Wind', '蜂军之风', 'B・F・W', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：1回合最多2次，自己场上有「蜂军」怪兽召唤·特殊召唤的场合，以那之内的1只为对象才能发动。比那只怪兽攻击力低的1只「蜂军」怪兽从卡组加入手卡。 ②：1回合1次，以自己场上1只持有等级的昆虫族怪兽为对象才能发动。这个回合，自己把作为对象的怪兽作为同调素材的场合，可以当作调整使用。'),
(86325573, 'Battlin'' Boxer Big Bandage', '燃烧拳击手 大绷带拳手', 'BK ビッグバンテージ', 'Effect Monster', 'Warrior', 'FIRE', 2, 1100, 1400, '这张卡1回合只有1次不会被战斗破坏。此外，1回合1次，选择自己墓地1只名字带有「燃烧拳击手」的怪兽或者除外的1只自己的名字带有「燃烧拳击手」的怪兽才能发动。自己场上的全部名字带有「燃烧拳击手」的怪兽变成和选择的怪兽相同等级。'),
(76589815, 'Battlin'' Boxer Cheat Commissioner', '燃烧拳击手 犯规拳击委员', 'BK チート・コミッショナー', 'XYZ Monster', 'Warrior', 'FIRE', 3, NULL, 1300, '3星怪兽×2 只要这张卡在场上表侧表示存在，可以攻击的对方怪兽必须作出攻击。此外，自己场上有这张卡以外的名字带有「燃烧拳击手」的怪兽存在的场合，对方不能把这张卡作为攻击对象。这张卡以外的自己的名字带有「燃烧拳击手」的怪兽进行战斗的攻击宣言时，把这张卡2个超量素材取除才能发动。把对方手卡确认，从那之中选1张魔法卡在自己场上盖放。'),
(47921178, 'Battlin'' Boxer Chief Second', '燃烧拳斗士 首席辅导员', 'BK チーフセコンド', 'Effect Monster', 'Warrior', 'FIRE', 4, 500, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时，若自己场上有战士族怪兽或炎属性怪兽存在则能发动。这张卡从手卡特殊召唤，那次攻击无效。那之后，场上1只怪兽直到结束阶段除外。 ②：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「燃烧拳击手」怪兽召唤。'),
(4549095, 'Battlin'' Boxer Counterpunch', '燃烧拳击手 反击拳手', 'BK カウンターブロー', 'Effect Monster', 'Warrior', 'FIRE', 3, NULL, 1100, '自己场上的名字带有「燃烧拳击手」的怪兽进行战斗的伤害步骤时把手卡或者墓地的这张卡从游戏中除外才能发动。那只怪兽的攻击力直到结束阶段时上升1000。「燃烧拳击手 反击拳手」的效果1回合只能使用1次。'),
(5361647, 'Battlin'' Boxer Glassjaw', '燃烧拳斗士 脆颌', 'BK グラスジョー', 'Effect Monster', 'Warrior', 'FIRE', 4, 2000, NULL, '①：这张卡被选择作为攻击对象的场合发动。这张卡破坏。 ②：这张卡被效果送去墓地时，以「燃烧拳击手 不堪一击拳手」以外的自己墓地1只「燃烧拳击手」怪兽为对象才能发动。那只怪兽加入手卡。'),
(79867938, 'Battlin'' Boxer Headgeared', '燃烧拳斗士 护头', 'BK ヘッドギア', 'Effect Monster', 'Warrior', 'FIRE', 4, 1000, 1800, '①：这张卡召唤时才能发动。从卡组把1只「燃烧拳击手」怪兽送去墓地。 ②：攻击表示的这张卡1回合只有1次不会被战斗破坏。'),
(46804536, 'Battlin'' Boxer King Dempsey', '燃烧拳斗士 拳王登普西', 'BK キング・デンプシー', 'XYZ Monster', 'Warrior', 'FIRE', 4, 2300, 1800, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组选1只4星以下的战士族·炎属性怪兽或者1张「燃烧拳」魔法·陷阱卡加入手卡或送去墓地。 ②：自己·对方回合可以发动。自己场上1个超量素材取除，以下效果适用。 ●这个回合中对方不能把自己场上的「燃烧拳击手」怪兽作为效果的对象。'),
(23232295, 'Battlin'' Boxer Lead Yoke', '燃烧拳斗士 拘束蛮兵 前导刺拳', 'BK 拘束蛮兵リードブロー', 'XYZ Monster', 'Warrior', 'FIRE', 4, 2200, 2000, '4星「燃烧拳击手」怪兽×2 ①：自己场上的「燃烧拳击手」怪兽被战斗·效果破坏的场合，可以作为那些「燃烧拳击手」怪兽之内的1只的代替而把这张卡1个超量素材取除。 ②：这张卡的超量素材被取除的场合发动。这张卡的攻击力上升800。'),
(83315222, 'Battlin'' Boxer Promoter', '燃烧拳斗士 推广人', 'BK プロモーター', 'Effect Monster', 'Warrior', 'FIRE', 4, 1700, 800, '这个卡名的①②③的效果1回合各能使用1次，这些效果发动的回合，自己不是「燃烧拳击手」怪兽不能特殊召唤。 ①：对方场上有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把这张卡解放才能发动。从卡组把「燃烧拳击手 推广人」以外的最多2只「燃烧拳击手」怪兽特殊召唤（同名卡最多1张）。 ③：把墓地的这张卡除外才能发动。自己场上的「燃烧拳击手」怪兽的等级全部上升1星或全部下降1星。'),
(61679541, 'Battlin'' Boxer Rabbit Puncher', '燃烧拳击手 击后脑勺拳手', 'BK ラビット・パンチャー', 'Effect Monster', 'Warrior', 'FIRE', 3, 800, 1000, '这张卡向守备表示怪兽攻击的场合，不进行伤害计算把那只怪兽破坏。'),
(24184846, 'Battlin'' Boxer Rib Gardna', '燃烧拳击手 内伸臂挡拳手', 'BK リベージ・ガードナー', 'Effect Monster', 'Warrior', 'FIRE', 3, 100, 1400, '把手卡或者墓地的这张卡从游戏中除外，选择自己场上1只名字带有「燃烧拳击手」的怪兽才能发动。选择的怪兽直到下次的自己的准备阶段时从游戏中除外。这个效果在对方回合也能发动。'),
(35537251, 'Battlin'' Boxer Shadow', '燃烧拳斗士 影击', 'BK シャドー', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 1400, '自己的主要阶段时才能发动。把自己场上的名字带有「燃烧拳击手」的超量怪兽1个超量素材取除，这张卡从手卡特殊召唤。「燃烧拳击手 假想敌拳手」的效果1回合只能使用1次。'),
(32750341, 'Battlin'' Boxer Sparrer', '燃烧拳斗士 练拳', 'BK スパー', 'Effect Monster', 'Warrior', 'FIRE', 4, 1200, 1400, '自己场上有名字带有「燃烧拳击手」的怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的场合，这个回合自己不能进行战斗阶段。'),
(68144350, 'Battlin'' Boxer Switchitter', '燃烧拳斗士 换架拳手', 'BK スイッチヒッター', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 1400, '这张卡的效果发动的回合，自己不是「燃烧拳击手」怪兽不能特殊召唤。 ①：这张卡召唤时，以自己墓地1只「燃烧拳击手」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(11522479, 'Battlin'' Boxer Uppercutter', '燃烧拳斗士 上钩拳手', 'BK アッパーカッター', 'Effect Monster', 'Warrior', 'FIRE', 4, 1600, 200, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤的场合才能发动。「燃烧拳击手 上勾拳手」以外的1只「燃烧拳击手」怪兽或1张「反击」反击陷阱卡从卡组加入手卡。 ②：这张卡被效果送去墓地的场合，可以从以下效果选择1个发动。 ●从自己墓地把「燃烧拳击手 上勾拳手」以外的1只「燃烧拳击手」怪兽特殊召唤。 ●从自己墓地把1张「反击」反击陷阱卡在自己场上盖放。'),
(13313278, 'Battlin'' Boxer Veil', '燃烧拳斗士 护罩', 'BK ベイル', 'Effect Monster', 'Warrior', 'FIRE', 4, NULL, 1800, '自己受到战斗伤害时才能发动。这张卡从手卡特殊召唤，自己基本分回复受到的伤害的数值。'),
(19688343, 'Battlin'' Boxing Cross Counter', '燃烧拳击・交叉反击', 'バーニングナックル・クロスカウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方把怪兽的效果发动时才能发动。自己场上1只「燃烧拳击手」超量怪兽或「No.」超量怪兽破坏，那个发动无效并破坏。那之后，以下效果可以适用。 ●和破坏的自己怪兽卡名不同的1只「燃烧拳击手」超量怪兽从额外卡组特殊召唤，把这张卡作为那只怪兽的超量素材。'),
(36916401, 'Battlin'' Boxing Spirits', '燃烧拳击・斗魂', 'バーニングナックル・スピリッツ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把卡组最上面的卡送去墓地，以自己墓地1只「燃烧拳击手」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(83755611, 'Baxia, Brightness of the Yang Zing', '辉龙星－蚣蝮', '輝竜星－ショウフク', 'Synchro Monster', 'Wyrm', 'LIGHT', 8, 2300, 2600, '调整＋调整以外的幻龙族怪兽1只以上 ①：这张卡同调召唤成功时，以最多有作为这张卡的同调素材的幻龙族怪兽的原本属性种类数量的场上的卡为对象才能发动。那些卡回到持有者卡组。 ②：1回合1次，以自己场上1张卡和自己墓地1只4星以下的怪兽为对象才能发动。那张场上的卡破坏，那只墓地的怪兽特殊召唤。'),
(4472318, 'Bayerock Dragon', '岩龙 裸岩甲龙', '岩竜ベアロック', 'Effect Monster', 'Dinosaur', 'EARTH', 6, 2300, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的手卡·场上的怪兽被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被对方破坏的场合，以这张卡以外的自己墓地最多2只恐龙族或岩石族的怪兽为对象才能发动（相同种族最多1只）。那些怪兽特殊召唤。'),
(47474172, 'Bayonater, the Baneful Barrel', '魔筒覗 刺刀鬼', '魔筒覗ベイオネーター', 'Effect Monster', 'Zombie', 'DARK', 1, 500, NULL, '①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降对方场上的怪兽数量×1000。'),
(36092504, 'Bayonet Punisher', '铳剑处刑', 'ベイオネット・パニッシャー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的场上·墓地的「枪管」怪兽种类的以下效果适用。自己场上有攻击力3000以上的怪兽存在的场合，对方不能对应这张卡的发动把效果发动。 ●融合：选对方场上1只怪兽除外。 ●同调：从对方的额外卡组把里侧表示的卡随机3张除外。 ●超量：选对方场上1张魔法·陷阱卡除外。 ●连接：从对方墓地选最多3张卡除外。'),
(43932352, 'Bayt''al-Hecahands', NULL, NULL, 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(79480466, 'Bazoo the Soul Eater Beast', '食魂魔兽 巴祖', '魂喰魔獣 バズー', 'XYZ Monster', 'Beast', 'EARTH', 4, 2500, 900, '4星怪兽×3 ①：只要这张卡在怪兽区域存在，从怪兽取除的超量素材不去墓地而除外。 ②：怪兽卡被送去墓地的场合才能发动（同一连锁上最多1次）。这张卡1个超量素材取除。 ③：这张卡的超量素材全部被取除的场合，以自己·对方的墓地的卡合计3张为对象才能发动。那些卡作为这张卡的超量素材。'),
(40133511, 'Bazoo the Soul-Eater', '噬魂者 巴兹', '魂を喰らう者 バズー', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 900, '可以从自己的墓地选最多3张怪兽从游戏中除外。每除外1张卡，在对方回合结束前，这张卡的攻击力上升300。这个效果在自己的回合只能用1次。'),
(50371210, 'Beacon of White', '光之引导', '光の導き', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：自己场上没有其他的「光之引导」存在，自己墓地有「青眼」怪兽3只以上存在的场合，以那之内的1只为对象才能把这张卡发动。那只怪兽效果无效特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽除外。 ②：装备怪兽以外的自己怪兽不能攻击，自己墓地有「青眼」怪兽存在的场合，装备怪兽在同1次的战斗阶段中可以作出最多有那个数量的攻击。'),
(6103114, 'Beaked Snake', '鸟嘴蛇', 'くちばしヘビ', 'Normal Monster', 'Reptile', 'EARTH', 3, 800, 900, '用长长的身体把对方缠起来，用大嘴进行攻击。'),
(84990171, 'Bean Soldier', '豌豆战士', 'ビーン・ソルジャー', 'Normal Monster', 'Plant', 'EARTH', 4, 1400, 1300, '使用剑和大豆攻击的植物战士，意外的强悍。'),
(80141055, 'Bearblocker', '熊掌魔手卫', 'クマモール', 'Effect Monster', 'Fiend', 'DARK', 3, 1600, NULL, '①：只要这张卡在怪兽区域存在，对方回合内，自己的魔法与陷阱区域盖放的卡不会被效果破坏。 ②：每次自己的魔法与陷阱区域盖放的卡被对方的效果破坏发动。这张卡的攻击力直到回合结束时上升800。'),
(27134209, 'Beargram, Shelled Emperor of the Forest Crown', '树冠之甲帝 贝桠蛄朗姆', '樹冠の甲帝ベアグラム', 'Effect Monster', 'Insect', 'EARTH', 9, 3400, 2900, '这张卡不能通常召唤。把自己的手卡·墓地3只昆虫族·植物族怪兽除外的场合才能从手卡·墓地特殊召唤。自己对「树冠之甲帝 比亚格拉姆」1回合只能有1次特殊召唤。 ①：只要这张卡在怪兽区域存在，对方不能对应自己的魔法·陷阱卡的效果的发动把怪兽的效果发动。 ②：1回合1次，自己主要阶段才能发动。昆虫族·植物族怪兽以外的场上的表侧表示怪兽全部破坏。这个回合，这张卡不能直接攻击。'),
(46009906, 'Beast Fangs', '猛兽之齿', '猛獣の歯', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '兽族才能装备。1只装备怪兽的攻击力和守备力上升300。'),
(78651105, 'Beast King Barbaros', '神兽王巴巴罗斯', '神獣王バルバロス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 8, 3000, 1200, '①：这张卡可以不用解放作通常召唤。 ②：这张卡的①的方法通常召唤的这张卡的原本攻击力变成1900。 ③：这张卡也能把3只怪兽解放作召唤。 ④：这张卡用这张卡的③的方法召唤成功的场合发动。对方场上的卡全部破坏。'),
(50675040, 'Beast King Unleashed', '兽王无尘', '獣王無塵', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果在同一连锁上只能发动1次。 ①：1回合1次，自己怪兽和与自身相同纵列的对方怪兽进行战斗的伤害步骤开始时才能发动。和那只自己怪兽相同纵列的卡全部回到持有者手卡。'),
(19028307, 'Beast Machine King Barbaros Ür', '兽神机王 巴巴罗斯乌尔', '獣神機王バルバロスUr', 'Effect Monster', 'Beast-Warrior', 'EARTH', 8, 3800, 1200, '①：这张卡可以从自己的手卡·场上·墓地把兽战士族怪兽和机械族怪兽各1只除外从手卡特殊召唤。 ②：这张卡的战斗让对方受到的战斗伤害变成0。'),
(21984400, 'Beast Magic Attack', '兽・魔・导', '獣・魔・導', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以把自己场上的魔力指示物的以下数量取除，那个效果发动。 ●2个：选自己场上1只「魔导兽」灵摆怪兽回到持有者手卡。 ●4个：从自己的额外卡组把1只表侧表示的「魔导兽」灵摆怪兽特殊召唤。那之后，可以给那只怪兽放置2个魔力指示物。 ●6个：从自己的额外卡组把1只表侧表示的灵摆怪兽特殊召唤。'),
(11761845, 'Beast of Talwar', '塔瓦弯刀恶魔', 'タルワール・デーモン', 'Normal Monster', 'Fiend', 'DARK', 6, 2400, 2150, '其双刀。即使是恶魔也只能由被允许的剑术高手所持有。'),
(20011655, 'Beast of Talwar - The Sword Summit', '魔剑达士－塔瓦弯刀恶魔', '魔剣達士－タルワール・デーモン', 'Effect Monster', 'Fiend', 'DARK', 7, 2400, 2150, '①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡1回合只有1次不会被对方的效果破坏。 ③：只要这张卡在怪兽区域存在，双方不能把其他怪兽作为装备魔法卡的效果的对象。'),
(83903521, 'Beast of the Pharaoh', '法老化身', 'ファラオの化身', 'Effect Monster', 'Zombie', 'EARTH', 3, 400, 600, '①：这张卡作为同调素材送去墓地的场合，以自己墓地1只4星以下的不死族怪兽为对象才能发动。那只不死族怪兽特殊召唤。'),
(9999961, 'Beast Rage', '兽怒', 'ビーストレイジ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的全部怪兽的攻击力上升从游戏中除外的自己的兽族以及鸟兽族怪兽数量×200的数值。'),
(84962466, 'Beast Rising', '兽毛竖起', 'ビーストライザー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把自己场上1只表侧表示的兽族·兽战士族怪兽除外，以自己场上1只兽族·兽战士族怪兽为对象才能发动。那只自己的兽族·兽战士族怪兽的攻击力上升因为这个效果发动而除外的怪兽的原本攻击力数值。'),
(35149085, 'Beast Soul Swap', '家畜虐杀', 'キャトルミューティレーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的1只兽族怪兽回手卡，从手卡特殊召唤1只和回手怪兽等级相同的兽族怪兽上场。'),
(21362970, 'Beast Striker', '毛兽攻击者', 'ビーストライカー', 'Effect Monster', 'Beast', 'EARTH', 4, 1850, 400, '丢弃1张手卡发动。从自己卡组把1只「毛扎」特殊召唤。这个效果1回合只能使用1次。'),
(72378329, 'Beast-Eyes Pendulum Dragon', '猛兽眼灵摆龙', 'ビーストアイズ・ペンデュラム・ドラゴン', 'Fusion Monster', 'Dragon', 'EARTH', 8, 3000, 2000, '龙族·暗属性怪兽＋兽族怪兽 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己场上的上记卡解放的场合可以从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡战斗破坏怪兽的场合发动。给与对方作为这张卡的融合素材的1只兽族怪兽的原本攻击力数值的伤害。'),
(16796157, 'Beast-Warrior Puma', '野兽战士 豹人', '野獣戦士ピューマン', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1600, 1000, '把这张卡解放才能发动。从自己的卡组·墓地把1只「异次元超能人·星斗罗宾」加入手卡。'),
(99426834, 'Beastking of the Swamps', '沼地的魔兽王', '沼地の魔獣王', 'Effect Monster', 'Aqua', 'WATER', 4, 1000, 1100, '这张卡可以代替融合怪兽素材的其中1只来融合。这个时候，其他的融合素材必须是指定的融合素材。'),
(81933259, 'Beastly Mirror Ritual', '恶魔镜的仪式', '悪魔鏡の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「恶魔镜」降临必要。场上和手卡加起来总共6颗星以上的怪兽作祭品。'),
(300302006, 'Beasts of Phantom', NULL, NULL, 'Skill Card', 'Yami Yugi', NULL, NULL, NULL, NULL, NULL),
(99011763, 'Beat Cop from the Underworld', '魔界巡逻课死亡警察', '魔界の警邏課デスポリス', 'Link Monster', 'Fiend', 'DARK', NULL, 1000, NULL, '怪兽2只 ①：卡名不同的暗属性怪兽2只为素材作连接召唤的这张卡得到以下效果。 ●把自己场上1只怪兽解放，以场上1张表侧表示的卡为对象才能发动。给那张卡放置1个警逻指示物。这个卡名的这个效果1回合只能使用1次。有警逻指示物放置的卡被战斗·效果破坏的场合，作为代替把那张卡1个警逻指示物取除。'),
(93850652, 'Beat, Bladesman Fur Hire', '空牙团的剑士 比特', '空牙団の剣士 ビート', 'Effect Monster', 'Warrior', 'EARTH', 3, 1200, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的剑士 比特」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「空牙团」怪兽特殊召唤的场合才能发动。从卡组把「空牙团的剑士 比特」以外的1只「空牙团」怪兽加入手卡。'),
(300202002, 'Beatdown!', NULL, NULL, 'Skill Card', 'Kaiba', NULL, NULL, NULL, NULL, NULL),
(46924949, 'Beatraptor', '领地恐龙', '縄張恐竜', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1400, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在主要怪兽区域存在，额外怪兽区域的怪兽的效果无效化。 ②：这张卡被战斗破坏时才能发动。从卡组把1只「领地恐龙」特殊召唤。'),
(27552504, 'Beatrice, Lady of the Eternal', '永远的淑女 贝缇丽彩', '永遠の淑女 ベアトリーチェ', 'XYZ Monster', 'Fairy', 'LIGHT', 6, 2500, 2800, '6星怪兽×2 这张卡也能把手卡1只「彼岸」怪兽送去墓地，在自己场上的「但丁」怪兽上面重叠来超量召唤。这个方法特殊召唤的回合，这张卡的①的效果不能发动。 ①：自己·对方回合1次，把这张卡1个超量素材取除才能发动。从卡组选1张卡送去墓地。 ②：这张卡被对方破坏送去墓地的场合才能发动。从额外卡组把1只「彼岸」怪兽无视召唤条件特殊召唤。'),
(29616941, 'Beautiful Beast Trainer', '美丽的魔物使', '美しき魔物使い', 'Normal Monster', 'Warrior', 'EARTH', 5, 1750, 1500, '平常难得一见的女性魔物使。鞭子一到手上性格就立即改变。'),
(16899564, 'Beautiful Headhuntress', '斩首的美女', '斬首の美女', 'Normal Monster', 'Warrior', 'EARTH', 4, 1600, 800, '在那美丽容貌的背后，却是个用刀子使许多人身首异处的女子。'),
(6625096, 'Beautunaful Princess', '鰤俏姬', '鰤っ子姫', 'Effect Monster', 'Fish', 'WATER', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时，把这张卡除外才能发动。从卡组把「鰤子姬」以外的1只4星以下的鱼族怪兽特殊召唤。'),
(32452818, 'Beaver Warrior', '路易斯', 'ルイーズ', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1200, 1500, '身体虽小，但在草原上具备高强的守备力。'),
(58400390, 'Beckoned by the World Chalice', '被星杯邀引者', '星杯に誘われし者', 'Normal Monster', 'Warrior', 'EARTH', 4, 1800, NULL, '和机怪日夜交战的青年。 当栖息于森林四周的机怪虫突然凶暴化之际，他依然寸步也不退让地持续防住对结界的入侵。见到那总是一马当先的雄姿就连森之民也振奋起来，但本人如此挥舞那枪其实只为守护他唯一的妹妹。'),
(16255442, 'Beckoning Light', '光之召集', '光の召集', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己手卡全部丢弃。那之后，从自己墓地选这个效果丢弃去墓地的卡数量的光属性怪兽加入手卡。'),
(1474910, 'Bee List Soldier', '小蜜蜂', 'ハチビー', 'Effect Monster', 'Insect', 'WIND', 1, 500, 400, '把这张卡和自己场上表侧表示存在的「小蜜蜂」以外的1只昆虫族怪兽解放发动。从自己卡组抽2张卡。'),
(49522489, 'Beelze Frog', '恶魔青蛙', '悪魔ガエル', 'Effect Monster', 'Aqua', 'WATER', 3, 1200, 800, '这张卡的攻击力上升自己墓地存在的「恶魂邪苦止」的数量×300的数值。'),
(34408491, 'Beelze of the Diabolic Dragons', '魔王龙 别西', '魔王龍 ベエルゼ', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 3000, '暗属性调整＋调整以外的怪兽1只以上 ①：场上的这张卡不会被战斗·效果破坏。 ②：这张卡的战斗或者对方的效果让自己受到伤害的场合发动。这张卡的攻击力上升受到的伤害的数值。'),
(8763963, 'Beelzeus of the Diabolic Dragons', '魔王超龙 别西宙斯', '魔王超龍 ベエルゼウス', 'Synchro Monster', 'Dragon', 'DARK', 10, 4000, 4000, '暗属性调整＋调整以外的怪兽2只以上 ①：这张卡不会被战斗·效果破坏。 ②：只要这张卡在怪兽区域存在，这张卡以外的自己怪兽不能攻击。 ③：1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽的攻击力变成0，自己基本分回复那个原本攻击力的数值。此外，这个回合这张卡的战斗发生的对对方玩家的战斗伤害变成一半。'),
(30587695, 'Beetron', '电子独角仙', 'カブトロン', 'Effect Monster', 'Insect', 'DARK', 4, 1600, 900, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1张表侧表示的魔法·陷阱卡送去墓地，以自己墓地1只4星以下的昆虫族怪兽为对象才能发动。那只昆虫族怪兽守备表示特殊召唤。'),
(2834264, 'Beetrooper Armor Horn', '骑甲虫 武装犄角', '騎甲虫アームド・ホーン', 'Link Monster', 'Insect', 'EARTH', NULL, 1000, NULL, '昆虫族怪兽2只 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是昆虫族怪兽不能特殊召唤。 ②：自己主要阶段才能发动。进行1只昆虫族怪兽的召唤。 ③：这张卡在墓地存在的场合，从自己墓地把3只其他的昆虫族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(51578214, 'Beetrooper Assault Roller', '骑甲虫 强袭滚球兵', '騎甲虫アサルト・ローラー', 'Effect Monster', 'Insect', 'EARTH', 4, 1600, 1400, '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。 ①：这张卡可以把自己墓地1只昆虫族怪兽除外，从手卡特殊召唤。 ②：这张卡的攻击力上升自己场上的其他的昆虫族怪兽数量×200。 ③：这张卡被战斗破坏时才能发动。从卡组把「骑甲虫 突击滚球兵」以外的1只「骑甲虫」怪兽加入手卡。'),
(91300233, 'Beetrooper Cruel Saturnas', '骑甲虫 残酷撒旦', '騎甲虫クルーエル・サターン', 'Fusion Monster', 'Insect', 'DARK', 5, 2400, 2000, '「骑甲虫」怪兽＋昆虫族怪兽 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把1张「骑甲虫」卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己不是昆虫族怪兽不能特殊召唤。 ③：昆虫族怪兽被表侧表示除外的场合，以除外的1只自己的「骑甲虫」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(87240371, 'Beetrooper Descent', '骑甲虫队空降作战', '騎甲虫隊降下作戦', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：在自己场上把1只「骑甲虫衍生物」（昆虫族·地·3星·攻/守1000）特殊召唤。那之后，自己场上有攻击力3000以上的昆虫族怪兽存在的场合，可以选场上1张魔法·陷阱卡破坏。'),
(1712616, 'Beetrooper Fly & Sting', '骑甲虫空杀舞队', '騎甲虫空殺舞隊', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「骑甲虫」怪兽存在，对方把怪兽的效果发动时才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在，自己场上有攻击力3000以上的昆虫族怪兽存在的场合，自己结束阶段从自己墓地把1只昆虫族怪兽除外才能发动。这张卡在自己场上盖放。'),
(64213017, 'Beetrooper Formation', '骑甲虫队战术机动', '騎甲虫隊戦術機動', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「骑甲虫」怪兽为对象才能发动。那只怪兽特殊召唤，自己失去那只怪兽的原本攻击力数值的基本分。这个效果特殊召唤的怪兽在这个回合不能攻击。 ②：自己场上的表侧表示的昆虫族怪兽被战斗·效果破坏的场合才能发动。在自己场上把1只「骑甲虫衍生物」（昆虫族·地·3星·攻/守1000）特殊召唤。'),
(13234975, 'Beetrooper Landing', '骑甲虫队登陆准备', '騎甲虫隊上陸態勢', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把昆虫族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：从自己墓地把2只昆虫族怪兽除外才能发动。墓地的这张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(88962829, 'Beetrooper Light Flapper', '骑甲虫 轻盈振翅兵', '騎甲虫ライト・フラッパー', 'Effect Monster', 'Insect', 'WATER', 6, 2000, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，从自己墓地的怪兽以及除外的自己怪兽之中以2只卡名不同的「骑甲虫」怪兽为对象才能发动。那些怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的卡以及那些同名卡的效果发动。 ②：对方怪兽的攻击宣言时才能发动。这张卡回到持有者手卡，那次攻击无效。'),
(39041550, 'Beetrooper Scale Bomber', '骑甲虫 鳞粉轰炸兵', '騎甲虫スケイル・ボム', 'Effect Monster', 'Insect', 'FIRE', 3, 1200, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有昆虫族怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：对方把场上的怪兽的效果发动时，把自己场上1只昆虫族怪兽解放才能发动。那只怪兽破坏。'),
(2656842, 'Beetrooper Scout Buggy', '骑甲虫 驾虫侦察兵', '騎甲虫スカウト・バギー', 'Effect Monster', 'Insect', 'WIND', 3, 1000, 300, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·卡组·墓地选1只「骑甲虫 侦察虫车兵」特殊召唤。 ②：只要这张卡在怪兽区域存在，自己不是昆虫族怪兽不能特殊召唤。'),
(40633084, 'Beetrooper Squad', '骑甲虫步兵分队', '騎甲虫歩兵分隊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把衍生物以外的自己场上1只昆虫族怪兽解放才能发动。那只怪兽的原本攻击力每1000最多1只的「骑甲虫衍生物」（昆虫族·地·3星·攻/守1000）在自己场上特殊召唤。'),
(65430555, 'Beetrooper Sting Lancer', '骑甲虫 蛰针枪兵', '騎甲虫スティンギー・ランス', 'Effect Monster', 'Insect', 'WIND', 7, 2400, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以自己墓地1只昆虫族怪兽和对方墓地1只怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到持有者卡组最下面。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「骑甲虫」魔法·陷阱卡加入手卡。'),
(6628343, 'Beginning Knight', '开辟之骑士', '開闢の騎士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 500, 2000, '「开辟之骑士」的①②的效果1回合各能使用1次。 ①：使用这张卡仪式召唤的「混沌战士」怪兽得到以下效果。 ●1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽除外。 ●这张卡战斗破坏对方怪兽送去墓地时才能发动。这张卡只再1次可以继续攻击。 ②：墓地的这张卡被除外的场合才能发动。从卡组把1张仪式魔法卡加入手卡。'),
(32360466, 'Beginning of Heaven and Earth', '天地开辟', '天地開闢', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把包含「混沌战士」怪兽或者「暗黑骑士 盖亚」怪兽1只以上的3只战士族怪兽给对方观看，对方从那之中随机选1只。那是「混沌战士」怪兽或者「暗黑骑士 盖亚」怪兽的场合，那只怪兽加入自己手卡，剩下的卡全部送去墓地。不是的场合，给对方观看的卡全部送去墓地。'),
(20374520, 'Begone, Knave!', '逐客令', '門前払い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡已在魔法与陷阱区域存在的状态，怪兽给与玩家战斗伤害的场合发动。那只怪兽回到持有者手卡。'),
(94022093, 'Behegon', '大肚海蛇', 'ベヒゴン', 'Normal Monster', 'Aqua', 'WATER', 4, 1350, 1000, '样子很怪的海蛇。特征是大口和大牙。'),
(13836592, 'Behemoth the King of a Hundred Battles', '百战王 贝希摩斯', '百戦王 ベヒーモス', 'Effect Monster', 'Beast', 'EARTH', 10, 2700, 1500, '这张卡可以把1只怪兽解放作上级召唤。 ①：这张卡召唤·特殊召唤的场合，以自己墓地1只兽族·兽战士族·鸟兽族怪兽为对象才能发动。那只怪兽加入手卡，这张卡的攻击力下降700。 ②：通常召唤的这张卡不受特殊召唤的怪兽发动的效果影响。 ③：自己结束阶段才能发动。这张卡的攻击力上升700。'),
(22996376, 'Behemoth the King of All Animals', '百兽王 贝希摩斯', '百獣王 ベヒーモス', 'Effect Monster', 'Beast', 'EARTH', 7, 2700, 1500, '这张卡可以把1只怪兽解放作上级召唤。 ①：这个方法上级召唤的这张卡的原本攻击力变成2000。 ②：这张卡上级召唤时，以为这张卡的上级召唤而解放的怪兽数量的自己墓地的兽族怪兽为对象才能发动。那些兽族怪兽加入手卡。'),
(300302043, 'Behold, Gate Guardian!', NULL, NULL, 'Skill Card', 'Paradox Broth', NULL, NULL, NULL, NULL, NULL),
(33731070, 'Beiige, Vanguard of Dark World', '暗黑界的尖兵 贝基', '暗黒界の尖兵 ベージ', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 1300, '①：这张卡被效果从手卡丢弃去墓地的场合发动。这张卡特殊召唤。'),
(33655493, 'Belial - Marquis of Darkness', '暗之侯爵 彼列', '闇の侯爵ベリアル', 'Effect Monster', 'Fiend', 'DARK', 8, 2800, 2400, '只要这张卡在场上表侧表示存在，对方不能选择「暗之侯爵 彼列」以外的自己场上表侧表示存在的怪兽作为攻击对象，也不能作为魔法·陷阱卡的效果的对象。'),
(300302044, 'Believe in your Bro', NULL, NULL, 'Skill Card', '', NULL, NULL, NULL, NULL, NULL),
(22953211, 'Bellcat Fighter', '铃猫战斗机', 'ベルキャットファイター', 'Link Monster', 'Machine', 'WIND', NULL, 2000, NULL, '包含衍生物的怪兽3只 ①：这张卡战斗破坏对方怪兽时才能发动。在自己场上把1只「铃猫衍生物」（机械族·风·4星·攻/守2000）守备表示特殊召唤。'),
(94662235, 'Bending Destiny', '命运弯曲', '運命湾曲', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的怪兽只有名字带有「命运女郎」的怪兽的场合才能发动。魔法·陷阱卡的发动，怪兽的召唤的其中1个无效，那张卡从游戏中除外。这个回合的结束阶段时，这个效果从游戏中除外的卡回到持有者手卡。'),
(73345237, 'Benghalancer the Resurgent', '回生之菩提枪兵', '廻生のベンガランゼス', 'Link Monster', 'Plant', 'LIGHT', NULL, 2500, NULL, '植物族怪兽2只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：双方的主要阶段，以对方场上1只效果怪兽为对象才能发动。自己受到那只怪兽的攻击力数值的伤害，那只怪兽回到持有者手卡。 ②：这张卡在墓地存在的场合，连接标记合计直到4为止从自己墓地把连接怪兽2只以上除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(77207191, 'Berfomet', '巴风特', 'バフォメット', 'Effect Monster', 'Fiend', 'DARK', 5, 1400, 1800, '①：这张卡召唤·反转召唤时才能发动。从卡组把1只「幻兽王 加泽尔」加入手卡。'),
(69601012, 'Berfomet the Mythical King of Phantom Beasts', '幻兽魔王 巴风特', '幻獣魔王バフォメット', 'Fusion Monster', 'Fiend', 'WIND', 6, 2400, 600, '种族不同的兽族·恶魔族·幻想魔族怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「有翼幻兽 奇美拉」使用。 ②：这张卡融合召唤的场合才能发动。从卡组把1只兽族·恶魔族·幻想魔族怪兽送去墓地。 ③：对方回合把墓地的这张卡除外，以「幻兽魔王 巴风特」以外的自己的除外状态的1只兽族·恶魔族·幻想魔族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(59808784, 'Berlineth the Firestorm Vassal', '炎帝家臣贝利尼斯', '炎帝家臣ベルリネス', 'Effect Monster', 'Pyro', 'FIRE', 3, 800, 1000, '「炎帝家臣 贝利尼斯」的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。这张卡从手卡特殊召唤。这个回合，自己不能从额外卡组把怪兽特殊召唤。 ②：这张卡为上级召唤而被解放的场合才能发动。把对方手卡确认，从那之中选1张卡直到结束阶段除外。'),
(20747792, 'Berry Magician Girl', '浆果魔术少女', 'ベリー・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'EARTH', 1, 400, 400, '①：这张卡召唤成功的场合才能发动。从卡组把1只「魔术少女」怪兽加入手卡。 ②：1回合1次，这张卡成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时才能发动。这张卡的表示形式变更，从卡组把「浆果魔术少女」以外的1只「魔术少女」怪兽特殊召唤。'),
(13744068, 'Berserk Archfiend', '狂战恶魔', 'バーサーク・デーモン', 'Effect Monster', 'Fiend', 'DARK', 6, 2000, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以包含恶魔族怪兽的自己场上最多2只表侧表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽破坏。 ②：这张卡的①的效果破坏怪兽时，以那个数量的对方场上的表侧表示怪兽为对象才能发动。这张卡的攻击力直到下次的自己回合的结束时上升作为对象的怪兽的原本攻击力的合计数值。'),
(85605684, 'Berserk Dragon', '狂暴死龙', 'バーサーク・デッド・ドラゴン', 'Effect Monster', 'Zombie', 'DARK', 8, 3500, NULL, '这张卡只能以「与恶魔的暗中交易」的效果进行特殊召唤。这张卡可以对对方场上所有怪兽各进行1次攻击。在自己每回合的结束阶段时，这张卡的攻击力下降500点。'),
(39168895, 'Berserk Gorilla', '愤怒的类人猿', '怒れる類人猿', 'Effect Monster', 'Beast', 'EARTH', 4, 2000, 1000, '当这张卡在场上以表侧守备表示存在时，这张卡被破坏。当这张卡处于可以进行攻击的状态时，这张卡的控制者必须让这张卡进行攻击。'),
(52497105, 'Berserk Scales', '蛮勇鳞粉', '蛮勇鱗粉', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽才能发动。选择的怪兽的攻击力上升1000，这个回合不能向对方玩家直接攻击。这个回合的结束阶段时，选择的怪兽的攻击力下降2000。'),
(15471265, 'Berserker Crush', '狂战士断碎', 'バーサーカークラッシュ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己墓地存在的1只怪兽从游戏中除外发动。直到这个回合的结束阶段时，自己场上表侧表示存在的1只「羽翼栗子球」的攻击力·守备力变成和除外怪兽相同数值。'),
(5402805, 'Berserker of the Tenyi', '天威之鬼神', '天威の鬼神', 'Link Monster', 'Wyrm', 'DARK', NULL, 3000, NULL, '包含连接怪兽的怪兽2只以上'),
(15381252, 'Berserker Soul', '狂战士之魂', '狂戦士の魂', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「狂战士之魂」在1回合只能发动1张。 ①：自己场上的怪兽直接攻击给与对方1500以下的伤害时，把手卡全部丢弃才能发动。自己卡组最上面的卡翻开，那是怪兽的场合，那只怪兽送去墓地，给与对方500伤害。那之后，直到怪兽以外被翻开为止让这个效果重复（最多7次）。翻开的卡是怪兽以外的场合，那张卡回到卡组最上面。'),
(56535497, 'Berserking', '狂怒', 'バーサーキング', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，选择场上表侧表示存在的2只兽族怪兽才能发动。直到那个回合的结束阶段时，选择的1只怪兽的攻击力变成一半，另1只怪兽的攻击力上升那个数值。这个效果在自己的主要阶段时以及对方的战斗阶段时才能发动。'),
(42901635, 'Berserkion the Electromagna Warrior', '电磁石之战士 狂勇机翁', '電磁石の戦士マグネット・ベルセリオン', 'Effect Monster', 'Rock', 'EARTH', 8, 3000, 2800, '这张卡不能通常召唤。从自己的手卡·场上·墓地把「电磁石战士α」「电磁石战士β」「电磁石战士γ」各1只除外的场合可以特殊召唤。 ①：从自己墓地把1只4星以下的「磁石战士」怪兽除外，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：这张卡被战斗或者对方的效果破坏的场合，以除外的自己的「电磁石战士α」「电磁石战士β」「电磁石战士γ」各1只为对象才能发动。那些怪兽特殊召唤。'),
(23969415, 'Beta Evolution Pill - Ultranscendance', '超越进化药贝塔', '超越進化薬β', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把包含恐龙族怪兽的2只怪兽解放才能发动。把持有解放的怪兽的攻击力合计以上的攻击力的1只5星以上的恐龙族怪兽从卡组·额外卡组特殊召唤。这张卡的发动后，直到回合结束时自己不是龙族·恐龙族·海龙族·幻龙族怪兽不能从额外卡组特殊召唤。'),
(79418928, 'Beta The Electromagnet Warrior', '电磁石战士贝塔', '電磁石の戦士β', 'Effect Monster', 'Rock', 'EARTH', 3, 1500, 1500, '「电磁石战士β」的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「电磁石战士β」以外的1只4星以下的「磁石战士」怪兽加入手卡。 ②：对方回合把这张卡解放才能发动。从卡组把1只4星「磁石战士」怪兽特殊召唤。'),
(39256679, 'Beta The Magnet Warrior', '磁石战士贝塔', '磁石の戦士β', 'Normal Monster', 'Rock', 'EARTH', 4, 1700, 1600, '用α、β、γ来变形合体。'),
(84079032, 'Bettan Bat', '面子蝙蝠', '面子蝙蝠', 'Tuner Monster', 'Winged Beast', 'EARTH', 1, NULL, NULL, '①：1回合最多3次，对方把怪兽召唤·特殊召唤的场合，以那之内的1只为对象才能发动。进行1次投掷硬币。表的场合，那只怪兽变成表侧攻击表示。里的场合，那只怪兽变成里侧守备表示。 ②：1回合1次，这张卡在怪兽区域存在的状态，场上的怪兽反转的场合或者表侧表示怪兽变成里侧守备表示的场合，以那之内的1只为对象才能发动（伤害步骤也能发动）。那只怪兽变成表侧攻击表示或里侧守备表示。'),
(300302045, 'Beware the Brothers Paradox!', NULL, NULL, 'Skill Card', 'Paradox Broth', NULL, NULL, NULL, NULL, NULL),
(35778533, 'Beware the White Forest', '切勿踏足白森之地', '白き森にはいるべからず', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有6星以上的幻想魔族或魔法师族的怪兽存在的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(22125101, 'Beyond the Pendulum', '超越灵摆・轨迹的魔术使', '軌跡の魔術師', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1200, NULL, '包含灵摆怪兽的效果怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡在额外怪兽区域连接召唤的场合，支付1200基本分才能发动。从卡组把1只灵摆怪兽加入手卡。这个回合自己只要灵摆召唤不成功，不能把怪兽的效果发动，自己的灵摆区域的卡的效果无效化。 ②：这张卡所连接区有原本等级不同的怪兽2只同时灵摆召唤的场合，以场上2张卡为对象才能发动。那些卡破坏。'),
(66500065, 'Bi''an, Earth of the Yang Zing', '地龙星－狴犴', '地竜星－ヘイカン', 'Effect Monster', 'Wyrm', 'EARTH', 3, 1600, NULL, '「地龙星-狴犴」的①的效果1回合只能使用1次。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「地龙星-狴犴」以外的1只「龙星」怪兽守备表示特殊召唤。 ②：1回合1次，对方的主要阶段以及战斗阶段才能发动。只用自己场上的「龙星」怪兽为同调素材作同调召唤。 ③：这张卡为同调素材的同调怪兽不会被战斗破坏。'),
(25655502, 'Bickuribox', '恶魔箱', 'デビル・ボックス', 'Fusion Monster', 'Fiend', 'DARK', 7, 2300, 2000, '「杀人小丑」＋「梦幻小丑」'),
(58685438, 'Bicorn Re''em', '二角兽', '二角獣レーム', 'Effect Monster', 'Beast', 'DARK', 4, 800, 1600, '这张卡作为同调召唤的素材送去墓地的场合，从对方卡组上面把2张卡送去墓地。'),
(83392426, 'Bicular', '二轮车人', 'ヴィークラー', 'Effect Monster', 'Machine', 'EARTH', 2, 200, 200, '这张卡被战斗破坏送去墓地时，可以从自己的手卡或者卡组把1只「单轮车人」在自己场上特殊召唤。'),
(61127349, 'Big Bang Shot', '爆炎穿击', 'ビッグバン・シュート', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升400。装备怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这张卡从场上离开时，装备怪兽从游戏中除外。'),
(32696942, 'Big Belly Knight', '三段腹骑士', '三段腹ナイト', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1600, '超量素材的这张卡为让超量怪兽把效果发动而被取除送去墓地的场合，可以从手卡把1只3星以下的怪兽特殊召唤。'),
(95472621, 'Big Burn', '大火葬', '大火葬', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '当对方发动以墓地里的怪兽卡为对象的卡时这张卡才能发动。将双方墓地里的怪兽卡全部除外。'),
(84808313, 'Big Evolution Pill', '大进化药', '大進化薬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只恐龙族怪兽解放才能把这张卡发动。这张卡发动后继续留在场上，用对方回合计算的第3回合的对方结束阶段破坏。 ①：只要这张卡在魔法与陷阱区域存在，自己在5星以上的恐龙族怪兽召唤的场合需要的解放可以不用。'),
(16768387, 'Big Eye', '眼球大王', '大王目玉', 'Flip Effect Monster', 'Fiend', 'DARK', 4, 1200, 1000, '反转：从自己卡组上面把最多5张卡确认，用喜欢的顺序回到卡组上面。'),
(91337277, 'Big Inflate Dragon', '巨膜充气龙', 'ビッグ・インフレート・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 8, 2500, 1500, '①：这张卡召唤的场合，从自己卡组上面把50张卡里侧除外才能发动。这张卡的攻击力直到回合结束时变成10000。'),
(53606874, 'Big Insect', '巨大蚂蚁', 'ビック・アント', 'Normal Monster', 'Insect', 'EARTH', 4, 1200, 1500, '住在密林里的巨大蚂蚁。攻击和守备都意外的强。'),
(51254277, 'Big Jaws', '大颚鲛', 'ビッグ・ジョーズ', 'Effect Monster', 'Fish', 'WATER', 3, 1800, 300, '这张卡攻击的场合，战斗阶段结束时从游戏中除外。'),
(42129512, 'Big Koala', '巨大考拉', 'ビッグ・コアラ', 'Normal Monster', 'Beast', 'EARTH', 7, 2700, 2000, '非常巨大的一种死亡树熊。性格温顺，但因为拥有非常强大的力量而被畏惧。'),
(89235196, 'Big One Warrior', '大一战士', 'ビッグ・ワン・ウォリアー', 'Effect Monster', 'Warrior', 'LIGHT', 1, 100, 600, '自己的主要阶段时，把这张卡以外的手卡1只1星怪兽送去墓地才能发动。这张卡从手卡特殊召唤。'),
(25247218, 'Big Piece Golem', '大块石人', 'ビッグ・ピース・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 5, 2100, NULL, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。'),
(65240384, 'Big Shield Gardna', '巨盾守卫者', 'ビッグ・シールド・ガードナー', 'Effect Monster', 'Warrior', 'EARTH', 4, 100, 2600, '①：只以里侧表示的这只怪兽1只为对象的魔法卡发动时发动。这张卡变成表侧守备表示，那个发动无效。 ②：这张卡被攻击的场合，伤害步骤结束时变成攻击表示。'),
(51562916, 'Big Wave Small Wave', '大波小波', '大波小波', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的水属性怪兽全破坏。之后，可以从手卡特殊召唤最多和破坏数同等数量的水属性怪兽上场。'),
(92714517, 'Big Welcome Labrynth', '欢迎大驾光临拉比丽斯', 'ビッグウェルカム・ラビュリンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的手卡·卡组·墓地把1只「拉比林斯迷宫」怪兽特殊召唤。那之后，自己场上1只怪兽回到手卡。 ②：把墓地的这张卡除外，以自己场上1只恶魔族怪兽为对象才能发动（自己场上有8星以上的恶魔族怪兽存在的场合，也能作为代替以对方场上1张卡为对象）。那张卡回到手卡。'),
(18322364, 'Big Whale', '巨鲸', 'ビッグ・ホエール', 'Effect Monster', 'Fish', 'WATER', 9, 1000, 3000, '这张卡上级召唤成功时，把这张卡解放才能发动。从卡组把3只3星的水属性怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(84677654, 'BIG Win!?', '大金星！？', '大金星！？', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '宣言从1到12的任意等级才能发动。双方玩家各自进行1次投掷硬币，都是表出现的场合，自己场上表侧表示存在的全部怪兽的等级变成宣言的等级。都是里出现的场合，自己失去宣言的等级数值×500基本分。'),
(59380081, 'Big-Tusked Mammoth', '巨角猛犸', 'ビッグホーン・マンモス', 'Effect Monster', 'Beast', 'EARTH', 5, 2000, 1000, '只要这张卡在场上表侧表示存在，对方场上怪兽召唤·反转召唤·特殊召唤的回合不能攻击。'),
(55461744, 'Big-Winged Berfomet', '大翼之巴风特', '大翼のバフォメット', 'Effect Monster', 'Fiend', 'DARK', 5, 1400, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。兽族·4星怪兽以及「合成兽融合」各最多1张从卡组加入手卡。这个效果的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。 ②：这张卡成为融合召唤的素材送去墓地的场合，以自己墓地1只幻想魔族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(80088625, 'Binary Blader', '二进制剑士', 'バイナル・ブレーダー', 'Link Monster', 'Cyberse', 'EARTH', NULL, 1800, NULL, '通常怪兽2只 ①：得到和这张卡互相连接的怪兽数量的以下效果。 ●1只以上：这张卡向对方怪兽攻击的攻击宣言时才能发动。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击，这张卡和对方怪兽进行战斗的场合，那只对方怪兽不会被那次战斗破坏。 ●2只：这张卡和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽除外。'),
(79016563, 'Binary Sorceress', '二进制女巫', 'バイナル・ソーサレス', 'Link Monster', 'Cyberse', 'EARTH', NULL, 1600, NULL, '衍生物以外的怪兽2只 ①：得到和这张卡互相连接的怪兽数量的以下效果。 ●1只以上：和这张卡互相连接的怪兽用和对方怪兽的战斗给与对方战斗伤害时才能发动。自己基本分回复那个数值。 ●2只：1回合1次，以自己场上2只表侧表示怪兽为对象才能发动。直到回合结束时，那2只怪兽之内1只的攻击力变成一半，另1只的攻击力上升那个数值。这个效果在对方回合也能发动。'),
(8058240, 'Binding Chain', '封印之锁', '封印の鎖', 'Normal Monster', 'Fairy', 'LIGHT', 3, 1000, 1100, '咯吱咯吱的勒住对方、拥有封印的力量。'),
(93437091, 'Bingo Machine, Go!!!', '宾果机器 冲！冲！', 'ビンゴマシーンGO！GO！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选以下的卡合计3张给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩下的卡回到卡组。 ●「青眼」怪兽 ●除「摇号机GO！GO！」外的有「青眼白龙」「青眼究极龙」其中任意种的卡名记述的魔法·陷阱卡'),
(7670542, 'Bio Plant', '生化植物', 'B・プラント', 'Normal Monster', 'Fiend', 'DARK', 3, 600, 1300, '地下研究所的试验大失败所产生的怪兽。'),
(3084730, 'Bio-Insect Armor', '昆虫机甲铠', '昆虫機甲鎧', 'Effect Monster', 'Insect', 'EARTH', 5, 1500, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己场上没有「昆虫机甲铠」存在的场合，以自己场上1只昆虫族怪兽为对象才能发动。这张卡当作装备卡使用给那只怪兽装备。这张卡以及用这个效果把这张卡装备的怪兽从场上离开的场合除外。 ②：有这张卡装备的怪兽在双方的战斗阶段以及主要阶段2内攻击力上升1500，守备力上升2000。'),
(58696829, 'Bio-Mage', '生化僧侣', 'バイオ僧侶', 'Normal Monster', 'Fairy', 'LIGHT', 3, 1150, 1000, '最新生物工艺产生的僧侣，掌握着无数的秘密。'),
(74130411, 'Biofalcon', '生化猎鹰', 'バイオファルコン', 'Effect Monster', 'Machine', 'LIGHT', 4, 1700, 1200, '这张卡在场上表侧表示存在的场合自己场上存在的机械族怪兽被战斗破坏送去墓地时，可以从自己卡组把1只攻击力1000以下的机械族怪兽加入手卡。'),
(84845628, 'Bird of Paradise Lost', '狱落鸟', '獄落鳥', 'Tuner Monster', 'Wyrm', 'DARK', 8, 2700, 1500, '①：这张卡的攻击力·守备力上升自己墓地的调整数量×100。 ②：1回合1次，把手卡1只调整送去墓地，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(75252099, 'Bird of Roses', '蔷薇鸟', 'ローズ・バード', 'Effect Monster', 'Plant', 'WIND', 4, 1800, 1500, '场上表侧攻击表示存在的这张卡被对方怪兽的攻击破坏送去墓地时，可以从自己卡组把2只植物族调整在自己场上表侧守备表示特殊召唤。'),
(45547649, 'Birdface', '鸟面人', 'バード・フェイス', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1600, 1600, '这张卡被战斗破坏送去墓地时，从卡组选1张「鹰身女郎」加入手卡。之后洗切卡组。'),
(5439384, 'Birth of the Prominence Flame', '炎雄爆诞', '炎雄爆誕', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地的守备力200的炎属性怪兽之中以调整1只和调整以外的怪兽1只为对象才能发动。那2只怪兽除外，把持有和那个等级合计相同等级的1只炎属性同调怪兽从额外卡组特殊召唤。'),
(35539880, 'Birthright', '正统的血统', '正統なる血統', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己墓地1只通常怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。'),
(92142169, 'Bite Bug', '大吃虫', 'パクバグ', 'Effect Monster', 'Insect', 'EARTH', 3, 300, 1000, '对方场上有超量怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功时，选择对方场上1只怪兽发动。选择的怪兽的攻击力下降300。'),
(50122883, 'Bite Shoes', '红靴子', '朱い靴', 'Flip Effect Monster', 'Fiend', 'DARK', 2, 500, 300, '反转：选择表侧表示的1只怪兽改变表示形式。'),
(44702857, 'Bitelon', '咬噬龙', 'バイトロン', 'Effect Monster', 'Reptile', 'WATER', 6, 2400, 1000, '这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(36211150, 'Bitron', '比特创机', 'ビットロン', 'Normal Monster', 'Cyberse', 'EARTH', 2, 200, 2000, '电子空间发现的新种。它的信息量非常少。'),
(36694815, 'Bitrooper', '比特骑兵', 'ビットルーパー', 'Effect Monster', 'Cyberse', 'EARTH', 4, 1500, 2000, '这个卡名的效果1回合只能使用1次。 ①：从手卡把1只2星以下的怪兽送去墓地才能发动。这张卡从手卡特殊召唤。'),
(2095764, 'Bixi, Water of the Yang Zing', '水龙星－赑屃', '水竜星－ビシキ', 'Effect Monster', 'Wyrm', 'WATER', 2, NULL, 2000, '「水龙星-赑屃」的①的效果1回合只能使用1次。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「水龙星-赑屃」以外的1只「龙星」怪兽攻击表示特殊召唤。 ②：1回合1次，对方的主要阶段以及战斗阶段才能发动。只用自己场上的「龙星」怪兽为同调素材作同调召唤。 ③：这张卡为同调素材的同调怪兽不受陷阱卡的效果影响。'),
(31677606, 'Black and White Wave', '黑白的波动', '黒白の波動', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '有同调怪兽在作为超量素材中的超量怪兽在场上存在的场合才能发动。选择场上1张卡从游戏中除外，从自己卡组抽1张卡。'),
(50896944, 'Black Brachios', '暗黑腕龙', '暗黒ブラキ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1800, 1100, '①：这张卡召唤成功时，以场上1只怪兽为对象才能发动。那只怪兽变成表侧守备表示。'),
(96029574, 'Black Brutdrago', '黑兽龙', 'ブラック・ブルドラゴ', 'Synchro Monster', 'Dragon', 'FIRE', 8, 3000, 2600, '调整＋调整以外的二重怪兽1只以上 1回合1次，可以从手卡把1只二重怪兽送去墓地，选择对方场上存在的1张魔法·陷阱卡破坏。这张卡被破坏送去墓地时，可以选择自己墓地存在的1只二重怪兽特殊召唤。这个效果特殊召唤的二重怪兽变成再度召唤的状态。'),
(67381587, 'Black Cat-astrophe', '黑猫瞪眼', '黒猫の睨み', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有里侧守备表示怪兽2只以上存在的场合，对方战斗阶段才能发动。那次战斗阶段结束。 ②：把墓地的这张卡除外，以包含「占术姬」怪兽的场上2只表侧表示怪兽为对象才能发动。那些怪兽变成里侧守备表示。'),
(61901281, 'Black Dragon Collapserpent', '暗黑龙 坍缩星蛇', '暗黒竜 コラプサーペント', 'Effect Monster', 'Dragon', 'DARK', 4, 1800, 1700, '这张卡不能通常召唤。从自己墓地把1只光属性怪兽除外的场合才能特殊召唤。这个方法的「暗黑龙 坍缩星蛇」的特殊召唤1回合只能有1次。 ①：这张卡从场上送去墓地的场合才能发动。从卡组把1只「辉白龙 暴源翼龙」加入手卡。'),
(56562619, 'Black Dragon Ninja', '黑龙忍者', '黒竜の忍者', 'Effect Monster', 'Beast', 'DARK', 7, 2800, 1600, '这张卡不用「忍者」怪兽或者「忍法」卡的效果不能特殊召唤。 ①：1回合1次，从手卡以及自己场上的表侧表示的卡之中把1只「忍者」怪兽和1张「忍法」卡送去墓地，以场上1只怪兽为对象才能发动。那只怪兽除外。这个效果在对方回合也能发动。 ②：表侧表示的这张卡从场上离开的场合发动。这张卡的效果除外的怪兽尽可能在原本持有者的场上特殊召唤。'),
(36262024, 'Black Dragon''s Chick', '黑龙之雏', '黒竜の雛', 'Effect Monster', 'Dragon', 'DARK', 1, 800, 500, '把自己场上表侧表示存在的这张卡送去墓地才能发动。从手卡把1只「真红眼黑龙」特殊召唤。'),
(75672051, 'Black Fang Magician', '黑牙的魔术师', '黒牙の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 4, 1700, 800, '这张卡在规则上也当作「超量龙」卡使用。 ①：这张卡被战斗·效果破坏的场合，以自己墓地1只魔法师族·暗属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(40279770, 'Black Feather Beacon', '黑羽的引导', '黒羽の導き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '卡的效果让自己受到伤害时才能发动。从手卡把1只4星以下的名字带有「黑羽」的怪兽特殊召唤。'),
(7602800, 'Black Feather Whirlwind', '黑翎之旋风', '黒羽の旋風', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己从额外卡组把暗属性同调怪兽特殊召唤的场合，以持有比那只怪兽低的攻击力的自己的墓地·除外状态的1只「黑羽」怪兽或「黑翼龙」为对象才能发动。那只怪兽特殊召唤。 ②：1回合1次，自己场上的暗属性怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1个黑羽指示物取除。'),
(71645242, 'Black Garden', '黑花园', 'ブラック・ガーデン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次「黑色花园」的效果以外让怪兽表侧表示召唤·特殊召唤发动。那些怪兽的攻击力变成一半。那之后，那控制者在对方场上把1只「蔷薇衍生物」（植物族·暗·2星·攻/守800）攻击表示特殊召唤。 ②：以持有和场上的全部植物族怪兽的攻击力合计相同攻击力的自己墓地1只怪兽为对象才能发动。这张卡以及场上的植物族怪兽全部破坏。全部破坏的场合，再把作为对象的怪兽特殊召唤。'),
(50323155, 'Black Horn of Heaven', '升天之黑角笛', '昇天の黒角笛', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方只把怪兽1只特殊召唤之际才能发动。那次特殊召唤无效，那只怪兽破坏。'),
(32754886, 'Black Illusion', '黑魔导幻像', 'ブラック・イリュージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的攻击力2000以上的魔法师族·暗属性怪兽直到回合结束时不会被战斗破坏，效果无效化，不受对方的效果影响。'),
(41426869, 'Black Illusion Ritual', '幻象之仪式', 'イリュージョンの儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「纳祭之魔」的降临必需。 ①：等级合计直到1以上的自己的手卡·场上的怪兽解放，从手卡把「纳祭之魔」仪式召唤。'),
(95506252, 'Black Jack the Shadow-Armored Knight', '影装骑士 黑杰克', '影装騎士 ブラック・ジャック', 'Synchro Monster', 'Warrior', 'DARK', 10, NULL, NULL, '调整＋调整以外的怪兽1只以上 ①：这张卡不会被战斗破坏。 ②：每次对方的魔法与陷阱区域有卡被放置发动。直到怪兽出现为止从自己卡组上面翻卡，那只怪兽当作装备魔法卡使用给这张卡装备。剩余用喜欢的顺序回到卡组下面。 ③：这张卡的攻击力·守备力上升给这张卡装备的怪兽的等级合计×300。 ④：给这张卡装备的怪兽的等级合计比21星大的场合这张卡破坏。'),
(55761792, 'Black Luster Ritual', '混沌的仪式', 'カオスの儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「混沌战士」的降临必需。 ①：从自己的手卡·场上把等级合计直到8以上的怪兽解放，从手卡把「混沌战士」仪式召唤。'),
(5405694, 'Black Luster Soldier', '混沌士兵', 'カオス・ソルジャー', 'Ritual Monster', 'Warrior', 'EARTH', 8, 3000, 2500, '「混沌的仪式」降临。'),
(72989439, 'Black Luster Soldier - Envoy of the Beginning', '混沌士兵 －开辟的使者－', 'カオス・ソルジャー －開闢の使者－', 'Effect Monster', 'Warrior', 'LIGHT', 8, 3000, 2500, '这张卡不能通常召唤。从自己墓地把光·暗属性怪兽各1只除外的场合可以特殊召唤。这张卡的①②的效果1回合只能有1次使用其中任意1个。 ①：以场上1只怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。那只怪兽除外。 ②：这张卡的攻击破坏对方怪兽时才能发动。这张卡只再1次可以继续攻击。'),
(77498348, 'Black Luster Soldier - Envoy of the Evening Twilight', '混沌战士 -宵暗的使者-', 'カオス・ソルジャー －宵闇の使者－', 'Effect Monster', 'Warrior', 'DARK', 8, 3000, 2500, '这张卡不能通常召唤。自己墓地的光属性和暗属性的怪兽数量相同的场合，把那之内的其中1个属性全部除外的场合才能特殊召唤。这张卡的属性也当作「光」使用。这张卡特殊召唤成功时，可以把为特殊召唤而除外的怪兽属性的以下效果发动。这个效果发动的回合，自己不能进行战斗阶段。 ●光：选择场上1只怪兽除外。 ●暗：对方手卡随机选1张直到对方的结束阶段时里侧表示除外。'),
(70551291, 'Black Luster Soldier - Legendary Swordsman', '传说之剑斗士 混沌士兵', '伝説の剣闘士 カオス・ソルジャー', 'Ritual Effect Monster', 'Warrior', 'EARTH', 8, 3000, 2500, '「混沌形态」「超战士的仪式」降临 这张卡不用仪式召唤不能特殊召唤。 ①：自己抽卡阶段的抽卡前，把手卡的这张卡给对方观看才能发动。作为这个回合进行通常抽卡的代替，从卡组把1张仪式魔法卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己战斗阶段中对方不能把效果发动。 ③：使用通常怪兽作仪式召唤的这张卡的攻击破坏对方怪兽时才能发动。对方场上的卡全部回到卡组。');